<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Zaid Workspace</title>
    <style>
        :root { color-scheme: dark; --bg:#0c0614; --panel:#181022; --panel2:#12091a; --line:rgba(255,255,255,.1); --text:#fbf8ff; --muted:#a99bb7; --accent:#d8b4fe; --danger:#fda4af; }
        * { box-sizing:border-box } body { margin:0; font:14px/1.45 Inter,ui-sans-serif,system-ui,sans-serif; background:radial-gradient(circle at 10% 0, #32104a, transparent 35rem),var(--bg); color:var(--text) } button,input,textarea { font:inherit } button { cursor:pointer } .app { min-height:100dvh; display:grid; grid-template-columns:220px minmax(0,1fr) 330px; gap:1px; background:var(--line) }.side,.calendar,.agenda { background:var(--panel); padding:24px }.side { display:flex; flex-direction:column; gap:20px }.brand { font-size:20px;font-weight:800;letter-spacing:-.04em;color:var(--accent) }.nav { display:grid;gap:6px }.nav button,.logout,.month-nav button,.task-actions button,.modal button { border:0;border-radius:10px;padding:10px 12px;color:var(--text);background:transparent;text-align:left }.nav button:hover,.logout:hover,.month-nav button:hover { background:rgba(255,255,255,.07) }.profile { margin-top:auto;padding-top:16px;border-top:1px solid var(--line);color:var(--muted);word-break:break-word }.logout { width:100%;margin-top:10px;background:rgba(255,255,255,.06);text-align:center }.calendar { min-width:0 }.topline,.agenda-head,.composer-head { display:flex;align-items:center;justify-content:space-between;gap:12px }.month-title { font-size:22px;font-weight:750;letter-spacing:-.04em }.month-nav { display:flex;gap:6px }.month-nav button,.primary { background:var(--accent);color:#170923;border:0;border-radius:10px;padding:9px 12px;font-weight:750 }.month-nav button { color:var(--text);background:rgba(255,255,255,.07) }.calendar-grid { display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px;margin-top:24px }.weekday { padding:8px;text-align:center;color:var(--muted);font-size:11px;text-transform:uppercase }.day { min-height:84px;border:1px solid var(--line);border-radius:11px;background:var(--panel2);color:var(--text);padding:9px;text-align:left;vertical-align:top }.day:hover,.day:focus-visible { outline:2px solid var(--accent);outline-offset:1px }.day.outside { opacity:.36 }.day.today .number { box-shadow:0 0 0 1px var(--accent) }.day.selected { background:#2e1743;border-color:var(--accent) }.number { display:inline-grid;place-items:center;width:25px;height:25px;border-radius:50% }.count { display:block;margin-top:10px;color:var(--accent);font-size:12px }.agenda { display:flex;flex-direction:column;gap:16px }.agenda-date { color:var(--muted) }.tasks { display:grid;gap:8px;max-height:37dvh;overflow:auto }.task { display:flex;gap:10px;align-items:flex-start;border:1px solid var(--line);border-radius:12px;padding:11px;background:var(--panel2) }.task input { margin-top:4px;accent-color:var(--accent) }.task-main { min-width:0;flex:1 }.task-title { font-weight:700;word-break:break-word }.task-meta { color:var(--muted);font-size:12px;margin-top:3px }.task-actions { display:flex;gap:4px }.task-actions button { padding:3px 5px;color:var(--muted) }.composer { margin-top:auto;border-top:1px solid var(--line);padding-top:16px }.composer textarea,.field input,.field textarea { width:100%;border:1px solid var(--line);border-radius:10px;background:#100817;color:var(--text);padding:10px;resize:vertical }.composer textarea { min-height:76px;margin:8px 0 }.status { min-height:20px;color:var(--muted);font-size:12px }.status.error { color:var(--danger) }.status.success { color:#86efac }.empty { color:var(--muted);padding:18px 0 }.modal { position:fixed;inset:0;background:rgba(0,0,0,.55);display:grid;place-items:center;padding:16px }.modal[hidden] { display:none }.modal-card { width:min(480px,100%);padding:20px;border:1px solid var(--line);border-radius:16px;background:var(--panel);box-shadow:0 20px 80px #000 }.field { display:grid;gap:5px;margin:12px 0;color:var(--muted);font-size:12px }.two { display:grid;grid-template-columns:1fr 1fr;gap:10px }.modal-actions { display:flex;justify-content:flex-end;gap:8px;margin-top:16px }.modal-actions button { background:rgba(255,255,255,.08);color:var(--text) }.modal-actions .primary { background:var(--accent);color:#170923 }.confirmation { margin-top:10px;border:1px solid var(--accent);border-radius:10px;padding:10px }.confirmation button { margin:8px 6px 0 0;border:0;border-radius:8px;padding:7px 9px;background:var(--accent);color:#170923;font-weight:700 }
        @media(max-width:900px){.app{grid-template-columns:1fr}.side{flex-direction:row;align-items:center}.nav{grid-template-columns:repeat(3,auto);margin-left:auto}.profile{display:none}.agenda{min-height:420px}.calendar-grid .day{min-height:64px}} @media(max-width:560px){.side,.calendar,.agenda{padding:16px}.day{min-height:50px;padding:4px}.count{margin-top:3px;font-size:10px}.weekday{padding:4px;font-size:9px}.two{grid-template-columns:1fr}}
    </style>
</head>
<body>
    <main class="app">
        <nav class="side" aria-label="Workspace navigation">
            <div class="brand">Zaid Workspace</div>
            <div class="nav"><button type="button" id="today-nav">Today</button><button type="button" id="calendar-nav">Calendar</button><button type="button" id="tasks-nav">Tasks</button></div>
            <div class="profile"><strong id="profile-name">Loading…</strong><br><span id="profile-email"></span><button class="logout" type="button" id="logout">Logout</button></div>
        </nav>
        <section class="calendar" aria-label="Calendar">
            <div class="topline"><div><div class="month-title" id="month-title">Calendar</div><div class="agenda-date">Your Zaid planning workspace</div></div><div class="month-nav"><button type="button" id="previous-month" aria-label="Previous month">←</button><button type="button" id="today">Today</button><button type="button" id="next-month" aria-label="Next month">→</button></div></div>
            <div class="calendar-grid" role="grid" aria-label="Month calendar" id="calendar-grid"></div>
        </section>
        <aside class="agenda" aria-label="Daily agenda">
            <div class="agenda-head"><div><strong id="agenda-title">Agenda</strong><div class="agenda-date" id="agenda-date"></div></div><button class="primary" type="button" id="new-task">+ Task</button></div>
            <div class="tasks" id="tasks" aria-live="polite"></div>
            <section class="composer" id="composer"><div class="composer-head"><strong>Ask Zaid</strong></div><textarea id="prompt" placeholder="Besok jam 10 follow up client 30 menit"></textarea><button class="primary" type="button" id="ask">Ask Zaid</button><div id="confirmation" class="confirmation" hidden></div><div class="status" id="status" role="status" aria-live="polite"></div></section>
        </aside>
    </main>
    <div class="modal" id="task-modal" hidden><form class="modal-card" id="task-form"><h2 id="form-title">New task</h2><input id="task-id" type="hidden"><label class="field">Title<input id="task-title" required maxlength="255"></label><label class="field">Description<textarea id="task-description"></textarea></label><div class="two"><label class="field">Date<input id="task-date" type="date"></label><label class="field">Time<input id="task-time" type="time"></label></div><label class="field"><span><input id="task-all-day" type="checkbox"> All day</span></label><div class="modal-actions"><button type="button" id="delete-task" hidden>Delete</button><button type="button" id="cancel-task">Cancel</button><button class="primary" type="submit">Save task</button></div></form></div>
<script>
const tokenKey='zaid_web_access_token', verificationKey='zaid_verification_id', phoneKey='zaid_phone_number';
const state={visibleMonth:new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedDate:new Date().toISOString().slice(0,10),monthDays:new Map(),pendingPrompt:null};
const $=id=>document.getElementById(id);
function clearSession(){[tokenKey,verificationKey,phoneKey].forEach(k=>localStorage.removeItem(k))}
function showStatus(message,type=''){const node=$('status');node.textContent=message||'';node.className='status '+type}
async function api(path,options={}){const token=localStorage.getItem(tokenKey);const response=await fetch('/api/v1'+path,{...options,headers:{Accept:'application/json',Authorization:`Bearer ${token}`,...(options.headers||{})}});const data=await response.json().catch(()=>({message:'Unexpected server response'}));if(!response.ok)throw data;return data}
function localDate(date){return new Date(date.getFullYear(),date.getMonth(),date.getDate())} function dateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`} function monthKey(date){return dateKey(date).slice(0,7)}
function setText(id,value){$(id).textContent=value||''}
function taskTime(task){return task.all_day?'All day':(task.scheduled_time||'No time').slice(0,5)}
async function boot(){if(!localStorage.getItem(tokenKey)){location.replace('/app');return}try{const [status,me]=await Promise.all([api('/onboarding/status'),api('/me')]);if(status.data.next_step!=='dashboard'){location.replace('/app');return}setText('profile-name',me.data.full_name);setText('profile-email',me.data.email);await refresh()}catch(error){clearSession();location.replace('/app')}}
async function refresh(){await Promise.all([loadMonth(),loadAgenda()])}
async function loadMonth(){const data=await api(`/calendar/month?month=${monthKey(state.visibleMonth)}`);state.monthDays=new Map(data.data.days.map(day=>[day.date,day]));renderCalendar()}
function renderCalendar(){const grid=$('calendar-grid');grid.replaceChildren();['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach(day=>{const node=document.createElement('div');node.className='weekday';node.textContent=day;grid.append(node)});setText('month-title',state.visibleMonth.toLocaleDateString(undefined,{month:'long',year:'numeric'}));const first=localDate(state.visibleMonth),start=new Date(first);start.setDate(1-first.getDay());const today=dateKey(new Date());for(let index=0;index<42;index++){const day=new Date(start);day.setDate(start.getDate()+index);const key=dateKey(day),summary=state.monthDays.get(key),button=document.createElement('button');button.type='button';button.className='day'+(day.getMonth()!==state.visibleMonth.getMonth()?' outside':'')+(key===state.selectedDate?' selected':'')+(key===today?' today':'');button.setAttribute('aria-label',`${day.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}${summary?.task_count?`, ${summary.task_count} tasks`:''}`);const number=document.createElement('span');number.className='number';number.textContent=String(day.getDate());button.append(number);if(summary?.task_count){const count=document.createElement('span');count.className='count';count.textContent=`${summary.task_count} task${summary.task_count===1?'':'s'}`;button.append(count)}button.addEventListener('click',()=>selectDate(key));grid.append(button)}}
async function selectDate(date){state.selectedDate=date;state.visibleMonth=new Date(`${date}T00:00:00`);await Promise.all([loadMonth(),loadAgenda()])}
async function loadAgenda(){const data=await api(`/agenda/day?date=${state.selectedDate}`);setText('agenda-date',new Date(`${state.selectedDate}T00:00:00`).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}));const tasks=$('tasks');tasks.replaceChildren();const items=data.data.items||[];setText('agenda-title',`Agenda · ${items.length}`);if(!items.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='No tasks scheduled.';tasks.append(empty);return}items.forEach(renderTask)}
function renderTask(task){const card=document.createElement('article');card.className='task';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=task.status==='completed';checkbox.setAttribute('aria-label',`Complete ${task.title}`);checkbox.addEventListener('change',async()=>{try{await api(`/tasks/${task.id}/complete`,{method:'POST'});showStatus('Task completed.','success');await refresh()}catch(error){checkbox.checked=false;showStatus(error.message||'Could not complete task.','error')}});const main=document.createElement('button');main.type='button';main.className='task-main';main.style.cssText='border:0;background:transparent;color:inherit;text-align:left;padding:0';const title=document.createElement('div');title.className='task-title';title.textContent=task.title;const meta=document.createElement('div');meta.className='task-meta';meta.textContent=`${taskTime(task)} · ${task.source_channel||'manual'}`;main.append(title,meta);main.addEventListener('click',()=>openTask(task));card.append(checkbox,main);$('tasks').append(card)}
function openTask(task=null){$('task-form').reset();$('task-id').value=task?.id||'';$('form-title').textContent=task?'Edit task':'New task';$('task-title').value=task?.title||'';$('task-description').value=task?.description||'';$('task-date').value=task?.scheduled_date||state.selectedDate;$('task-time').value=(task?.scheduled_time||'').slice(0,5);$('task-all-day').checked=!!task?.all_day;$('delete-task').hidden=!task;$('task-modal').hidden=false}
function closeTask(){ $('task-modal').hidden=true }
async function saveTask(event){event.preventDefault();const id=$('task-id').value,allDay=$('task-all-day').checked,payload={title:$('task-title').value.trim(),description:$('task-description').value.trim()||null,scheduled_date:$('task-date').value||null,scheduled_time:allDay?null:($('task-time').value?`${$('task-time').value}:00`:null),timezone:'Asia/Jakarta',all_day:allDay};try{await api(id?`/tasks/${id}`:'/tasks',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});closeTask();showStatus('Task saved.','success');await refresh()}catch(error){showStatus(error.message||'Could not save task.','error')}}
async function deleteTask(){const id=$('task-id').value;if(!id||!confirm('Delete this task?'))return;try{await api(`/tasks/${id}`,{method:'DELETE'});closeTask();showStatus('Task deleted.','success');await refresh()}catch(error){showStatus(error.message||'Could not delete task.','error')}}
function renderConfirmation(data){const box=$('confirmation');box.replaceChildren();const question=document.createElement('div');question.textContent=data.confirmation?.question||'Confirm this action?';const yes=document.createElement('button');yes.textContent='Confirm';yes.onclick=()=>confirmPrompt(true);const no=document.createElement('button');no.textContent='Cancel';no.onclick=()=>confirmPrompt(false);box.append(question,yes,no);box.hidden=false}
async function ask(){const text=$('prompt').value.trim();if(!text)return;const button=$('ask');button.disabled=true;try{const data=await api('/prompts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text})});if(data.data.requires_confirmation){state.pendingPrompt=data.data.prompt_request_id;renderConfirmation(data.data);showStatus(data.data.human_response||'Confirmation required.');return}$('prompt').value='';showStatus(data.data.human_response||data.message,'success');await refresh()}catch(error){showStatus(error.message||'Could not process prompt.','error')}finally{button.disabled=false}}
async function confirmPrompt(confirmed){if(!state.pendingPrompt)return;try{const data=await api(`/prompts/${state.pendingPrompt}/confirm`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed})});state.pendingPrompt=null;$('confirmation').hidden=true;$('prompt').value='';showStatus(data.data.human_response||'Prompt updated.','success');if(confirmed)await refresh()}catch(error){showStatus(error.message||'Could not confirm prompt.','error')}}
$('previous-month').onclick=async()=>{state.visibleMonth.setMonth(state.visibleMonth.getMonth()-1);await loadMonth()};$('next-month').onclick=async()=>{state.visibleMonth.setMonth(state.visibleMonth.getMonth()+1);await loadMonth()};$('today').onclick=async()=>selectDate(dateKey(new Date()));$('today-nav').onclick=async()=>selectDate(dateKey(new Date()));$('calendar-nav').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('tasks-nav').onclick=()=>$('tasks').scrollIntoView({behavior:'smooth'});$('new-task').onclick=()=>openTask();$('cancel-task').onclick=closeTask;$('delete-task').onclick=deleteTask;$('task-form').onsubmit=saveTask;$('ask').onclick=ask;$('logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST'})}catch(error){}clearSession();location.replace('/app')};boot();
</script>
</body>
</html>
